export type GetNotesInput = { q: string }

export type GetNotesItem = { id: number; title: string; updatedAt?: string }

export type GetNotesResponse = { items: { id: number; title: string; updatedAt?: string }[] }

export async function getNotes(input: GetNotesInput, signal?: AbortSignal): Promise<GetNotesResponse> {
  const url = new URL("/api/notes", "https://notes.example")
  url.searchParams.set("q", String(input.q))
  const response = await fetch(url, {
    method: "GET",
    signal,
    headers: {
      accept: 'application/json',
    },
  })
  if (!response.ok) {
    throw new Error("GET /api/notes failed" + ` (${response.status})`)
  }
  return (await response.json()) as GetNotesResponse
}
